    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, trigger, channel_mode):
        main = {}
        other = {}
        main_changes = 0
        other_changes = 0
        main_total = 0
        other_total = 0
        log = 0
        in_tx = False
        tx_conn = None
        tx_snapshot = None

        def apply(conn, op, key, value):
            nonlocal main_changes, other_changes, main_total, other_total, log
            if op == "put":
                if conn == "main":
                    if key in main:
                        if put_mode == "ignore":
                            return
                        if put_mode == "replace":
                            main[key] = value
                            main_changes += 1
                            main_total += 1
                            if trigger:
                                log += 1
                            return
                        if put_mode == "upsert":
                            main[key] = value
                            main_changes += 1
                            main_total += 1
                            if trigger:
                                log += 1
                            return
                    else:
                        main[key] = value
                        main_changes += 1
                        main_total += 1
                        if trigger:
                            log += 1
                else:
                    if key in other:
                        if put_mode == "ignore":
                            return
                        if put_mode == "replace":
                            other[key] = value
                            other_changes += 1
                            other_total += 1
                            if trigger:
                                log += 1
                            return
                        if put_mode == "upsert":
                            other[key] = value
                            other_changes += 1
                            other_total += 1
                            if trigger:
                                log += 1
                            return
                    else:
                        other[key] = value
                        other_changes += 1
                        other_total += 1
                        if trigger:
                            log += 1
            elif op == "update":
                if conn == "main":
                    if key in main:
                        main[key] = value
                        main_changes += 1
                        main_total += 1
                        if trigger:
                            log += 1
                else:
                    if key in other:
                        other[key] = value
                        other_changes += 1
                        other_total += 1
                        if trigger:
                            log += 1
            elif op == "delete":
                if conn == "main":
                    if key in main:
                        del main[key]
                        main_changes += 1
                        main_total += 1
                        if trigger:
                            log += 1
                else:
                    if key in other:
                        del other[key]
                        other_changes += 1
                        other_total += 1
                        if trigger:
                            log += 1

        for action in actions:
            op = action.get("op")
            conn = action.get("connection", "main")
            key = action.get("key")
            value = action.get("value")
            if op == "begin":
                if not in_tx:
                    in_tx = True
                    tx_conn = conn
                    if conn == "main":
                        tx_snapshot = (dict(main), main_changes, main_total, log)
                    else:
                        tx_snapshot = (dict(other), other_changes, other_total, log)
            elif op == "commit":
                if in_tx:
                    in_tx = False
                    tx_conn = None
                    tx_snapshot = None
            elif op == "rollback":
                if in_tx:
                    if tx_conn == "main":
                        main, main_changes, main_total, log = tx_snapshot
                    else:
                        other, other_changes, other_total, log = tx_snapshot
                    in_tx = False
                    tx_conn = None
                    tx_snapshot = None
            else:
                apply(conn, op, key, value)

        if channel_mode == "changes":
            channel = main_changes
        elif channel_mode == "total":
            channel = main_total
        else:
            channel = main_total + other_total
        committed = dict(main)
        committed.update(other)
        return channel, len(committed), sum(committed.values())

    def consistent(put_mode, trigger, channel_mode):
        for receipt in history:
            actions = receipt.get("actions", [])
            observed = receipt.get("observed", {})
            ch, cc, cs = simulate(actions, put_mode, trigger, channel_mode)
            if ch != observed.get("channel"):
                return False
            if cc != observed.get("committed_count"):
                return False
            if cs != observed.get("committed_sum"):
                return False
        return True

    candidates = []
    for put_mode in ("ignore", "replace", "upsert"):
        for trigger in (False, True):
            for channel_mode in ("changes", "total", "both"):
                if consistent(put_mode, trigger, channel_mode):
                    candidates.append((put_mode, trigger, channel_mode))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    values = []
    for put_mode, trigger, channel_mode in candidates:
        ch, cc, cs = simulate(actions, put_mode, trigger, channel_mode)
        if goal == "channel":
            values.append(ch)
        elif goal == "committed_count":
            values.append(cc)
        elif goal == "committed_sum":
            values.append(cs)
        else:
            return {"value": None, "unresolved": True}

    if len(set(values)) == 1:
        return {"value": values[0], "unresolved": False}
    return {"value": None, "unresolved": True}

